package com.smarthub.plus;
import android.app.AlertDialog;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;

/** Real satellite and transponder directory from the user's channel export. */
public final class SatelliteBrowserActivity extends HubActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private List<ReceiverCatalog.Sat> satellites=Collections.emptyList();private ListView list;private TextView status;private boolean closed;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=col();root.setBackground(ReceiverPanelStyle.panel(this));root.setLayoutDirection(ar?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);root.setPadding(dp(26),dp(18),dp(26),dp(18));LinearLayout head=row();head.addView(text(tx("الأقمار والترددات","Satellites and transponders"),27,true),new LinearLayout.LayoutParams(0,-2,1));Button back=button(tx("رجوع","Back"));back.setOnClickListener(v->finish());head.addView(back);root.addView(head);status=text(tx("قراءة ملف القنوات…","Reading channel catalogue…"),14,false);status.setTextColor(MUTED);root.addView(status);list=new ListView(this);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));TextView hint=text(tx("OK لعرض قنوات القمر · ضغط مطوّل لعرض الترددات المحفوظة","OK for satellite channels · long press for saved transponders"),13,false);hint.setTextColor(ACCENT);root.addView(hint);android.widget.FrameLayout frame=new android.widget.FrameLayout(this);android.widget.FrameLayout.LayoutParams panel=new android.widget.FrameLayout.LayoutParams(Math.min(dp(650),getResources().getDisplayMetrics().widthPixels-dp(70)),Math.min(dp(490),getResources().getDisplayMetrics().heightPixels-dp(30)),Gravity.CENTER);frame.addView(root,panel);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));setContentView(frame);list.setOnItemClickListener((p,v,index,id)->{startActivity(new Intent(this,ReceiverChannelsActivity.class).putExtra("satellite",satellites.get(index).id));finish();});list.setOnItemLongClickListener((p,v,index,id)->{ReceiverCatalog.Sat sat=satellites.get(index);io.execute(()->{List<String> rows=ReceiverCatalog.get(this).transponders(sat.id);runOnUiThread(()->{if(!closed)new AlertDialog.Builder(this).setTitle(sat.label()+" · CHL").setItems(rows.toArray(new String[0]),(d,n)->{}).setNegativeButton(tx("إغلاق","Close"),null).show();});});return true;});io.execute(()->{ReceiverCatalog catalog=ReceiverCatalog.get(this);catalog.ensure();List<ReceiverCatalog.Sat> found=catalog.satellites();runOnUiThread(()->{if(closed)return;satellites=found;status.setText(tx("أقمار ملف CHL: ","CHL satellites: ")+found.size());list.setAdapter(new BaseAdapter(){public int getCount(){return satellites.size();}public Object getItem(int p){return satellites.get(p);}public long getItemId(int p){return satellites.get(p).id;}public View getView(int p,View recycled,ViewGroup parent){TextView row=text(satellites.get(p).label()+"\n"+satellites.get(p).band,19,true);row.setPadding(dp(18),dp(14),dp(18),dp(14));row.setBackground(ReceiverPanelStyle.row(SatelliteBrowserActivity.this));row.setTextColor(ReceiverPanelStyle.GOLD);return row;}});});});}
 @Override protected void onDestroy(){closed=true;io.shutdownNow();super.onDestroy();}
}
